    throw const FormatException('not an rsaEncryption SPKI');
  }
  // BIT STRING: one unused-bits octet, then SEQUENCE{INTEGER n, INTEGER e}.
  final rsa = _DerReader(_DerReader(content.take(0x03).sublist(1)).take(0x30));
  return RsaPublicKey(
